setup_files.status.ts:
export enum Status {
  Pending = 'pending',
  Active = 'active',
  Closed = 'closed',
}

export function canTransition(from: Status, to: Status): boolean {
  if (from === Status.Pending && to === Status.Active) return true;
  if (from === Status.Active && to === Status.Closed) return true;
  return false;
}

export function label(status: Status): string {
  return status.toUpperCase();
}

